import{S as o}from"./chunks/ScenarioFlow.Fum56OVg.js";import{o as e,c as t,a2 as a,E as s}from"./chunks/framework.BFIoSwgX.js";const m=JSON.parse('{"title":"Сценарии использования","description":"Что можно делать с SymbolTrail: онбординг, объяснение кода, ревью, импакт-анализ, история изменений, подготовка задач, спецификаций и тестов, SDD с OpenSpec.","frontmatter":{"title":"Сценарии использования","description":"Что можно делать с SymbolTrail: онбординг, объяснение кода, ревью, импакт-анализ, история изменений, подготовка задач, спецификаций и тестов, SDD с OpenSpec.","section":"Начало работы","pageClass":"st-use-cases-page"},"headers":[],"relativePath":"use-cases.md","filePath":"use-cases.md"}'),i={name:"use-cases.md"},n=Object.assign(i,{setup(r){return(c,l)=>(e(),t("div",null,[l[0]||(l[0]=a('<h1 id="сценарии-использования" tabindex="-1">Сценарии использования <a class="header-anchor" href="#сценарии-использования" aria-label="Permalink to &quot;Сценарии использования&quot;">​</a></h1><p>SymbolTrail превращает код в понятную структуру. С его помощью можно мгновенно находить объявления, прослеживать цепочки вызовов, выявлять всех потребителей функции и изучать историю связанных коммитов.</p><p>Исследовать эти данные можно двумя путями:</p><ul><li>👨‍💻 <strong>Самостоятельно</strong> через удобный <a href="/symbolTrail/local-ui.html">локальный веб-интерфейс</a>.</li><li>🤖 <strong>С помощью ИИ-агента</strong>, передав ему контекст через протокол <a href="/symbolTrail/mcp.html">MCP</a>.</li></ul><p>В примерах ниже показано, как агент, опираясь на граф знаний и актуальные исходники, самостоятельно готовит объяснения, формулирует технические задачи, пишет спецификации и подбирает тесты. Все необходимые проверки и команды он выполняет своими встроенными средствами.</p><blockquote><p>💡 <strong>Важно:</strong> Перед началом исследования не забудьте <a href="/symbolTrail/indexing.html">обновить индекс</a> и убедиться, что все нужные репозитории объединены в один набор.</p></blockquote><h3 id="ревью" tabindex="-1">Ревью <a class="header-anchor" href="#ревью" aria-label="Permalink to &quot;Ревью&quot;">​</a></h3><p>Проверьте внешних потребителей изменённого объявления: кто его использует, какие ожидания могут нарушиться и что нужно проверить.</p><div class="info custom-block"><p class="custom-block-title">Запрос агенту</p><p>Проведи ревью текущего диффа. Проверь внешних потребителей изменённых функций и обработку ошибок. Для каждого замечания укажи условие возникновения, последствие и место в коде.</p></div>',9)),s(o,{scenario:"review"}),l[1]||(l[1]=a('<div class="tip custom-block"><p class="custom-block-title">Результат</p><p>Подтверждённые замечания и список проверенных потребителей. Вердикт формирует агент после чтения кода.</p></div><p>Начните с <a href="/symbolTrail/tools.html#review">review</a>. Неизвестные переходы уточняйте через <a href="/symbolTrail/tools.html#callers">callers</a> и <a href="/symbolTrail/tools.html#callees">callees</a>.</p><h3 id="импакт-анализ-и-blast-radius" tabindex="-1">Импакт-анализ и blast radius <a class="header-anchor" href="#импакт-анализ-и-blast-radius" aria-label="Permalink to &quot;Импакт-анализ и blast radius&quot;">​</a></h3><p>Импакт-анализ объясняет, что изменение означает для потребителей. Blast radius показывает область возможных последствий: символы, файлы и репозитории, которые стоит проверить.</p><div class="info custom-block"><p class="custom-block-title">Запрос агенту</p><p>Я хочу изменить контракт foo. Найди прямых и косвенных потребителей, включая другие репозитории этого индекса. Покажи, где нужны правки, а где достаточно проверки, и какие зависимости остались неясными.</p></div>',5)),s(o,{scenario:"impact"}),l[2]||(l[2]=a('<div class="tip custom-block"><p class="custom-block-title">Результат</p><p>Область влияния, связанные контракты и план проверок. Достижимость по графу означает возможную зависимость, а не доказанный сбой.</p></div><p>Используйте <a href="/symbolTrail/tools.html#callers">callers</a>, <a href="/symbolTrail/tools.html#map">map</a> и, если дифф уже есть, <a href="/symbolTrail/tools.html#review">review</a>. Кросс-репозиторные связи доступны внутри одного <a href="/symbolTrail/indexing.html">индекса</a>.</p><h3 id="диагностика-ошибки" tabindex="-1">Диагностика ошибки <a class="header-anchor" href="#диагностика-ошибки" aria-label="Permalink to &quot;Диагностика ошибки&quot;">​</a></h3><p>Начните с наблюдаемого сбоя и восстановите путь данных между точкой входа и проблемным местом. Проверьте функцию, где проявилась ошибка, и вызывающий её код.</p><div class="info custom-block"><p class="custom-block-title">Запрос агенту</p><p>При таком входе получается неверный результат. Найди путь выполнения, сформулируй проверяемую причину и предложи минимальный сценарий воспроизведения. Покажи, где добавить регрессионный тест.</p></div>',5)),s(o,{scenario:"debug"}),l[3]||(l[3]=a('<div class="tip custom-block"><p class="custom-block-title">Результат</p><p>Гипотеза с опорой на исходники, воспроизведение и проверка, отличающая ошибочное поведение от исправленного.</p></div><p>Начните с <a href="/symbolTrail/tools.html#find">find</a>, затем исследуйте <a href="/symbolTrail/tools.html#callers">callers</a> и <a href="/symbolTrail/tools.html#callees">callees</a>. Для работы агента с исправлением доступен навык <a href="/symbolTrail/mcp.html#навыки-агента">graph-bugfix</a>.</p><h2 id="понять-проект" tabindex="-1">Понять проект <a class="header-anchor" href="#понять-проект" aria-label="Permalink to &quot;Понять проект&quot;">​</a></h2><h3 id="онбординг" tabindex="-1">Онбординг <a class="header-anchor" href="#онбординг" aria-label="Permalink to &quot;Онбординг&quot;">​</a></h3><p>Найдите основные подсистемы, точки входа и связи между ними. Это поможет выбрать порядок знакомства с проектом и не читать все файлы подряд.</p><div class="info custom-block"><p class="custom-block-title">Запрос агенту</p><p>Помоги разобраться в проекте: выдели основные модули, найди точки входа и проследи один пользовательский сценарий. Предложи порядок чтения файлов.</p></div>',6)),s(o,{scenario:"onboarding"}),l[4]||(l[4]=a('<div class="tip custom-block"><p class="custom-block-title">Результат</p><p>Обзор устройства проекта и небольшой список файлов, с которых стоит начать.</p></div><p>Начните с <a href="/symbolTrail/tools.html#map">map</a>, затем уточните объявления через <a href="/symbolTrail/tools.html#find">find</a> и вызовы через <a href="/symbolTrail/tools.html#callees">callees</a>.</p><h3 id="объяснить-код" tabindex="-1">Объяснить код <a class="header-anchor" href="#объяснить-код" aria-label="Permalink to &quot;Объяснить код&quot;">​</a></h3><p>Посмотрите, что функция вызывает и где её используют. Граф помогает найти переходы между файлами. Исходники объясняют условия, вычисления и обработку ошибок.</p><div class="info custom-block"><p class="custom-block-title">Запрос агенту</p><p>Объясни, как работает foo: откуда поступают данные, какие функции вызываются, что возвращается и как обрабатываются ошибки. Приведи ссылки на код.</p></div>',5)),s(o,{scenario:"explain"}),l[5]||(l[5]=a('<div class="tip custom-block"><p class="custom-block-title">Результат</p><p>Объяснение поведения с адресами определений и важных мест использования.</p></div><p>Используйте <a href="/symbolTrail/tools.html#find">find</a>, <a href="/symbolTrail/tools.html#callees">callees</a> и <a href="/symbolTrail/tools.html#callers">callers</a>.</p><h3 id="кто-менял-код" tabindex="-1">Кто менял код <a class="header-anchor" href="#кто-менял-код" aria-label="Permalink to &quot;Кто менял код&quot;">​</a></h3><p>У текущего объявления можно посмотреть авторов и связанные коммиты. Если известен SHA или ключ задачи, найдите затронутые объявления и изучите их потребителей.</p><div class="info custom-block"><p class="custom-block-title">Запрос агенту</p><p>Кто менял foo? Покажи связанные коммиты и упомянутые задачи. Помоги понять контекст изменений по сообщениям коммитов и коду.</p></div>',5)),s(o,{scenario:"history"}),l[6]||(l[6]=a('<div class="tip custom-block"><p class="custom-block-title">Результат</p><p>Авторы, связанные коммиты и точки для дальнейшего исследования. Индекс опирается на blame текущего кода; полную историю и исторические диффы смотрите через Git.</p></div><p>Начать можно с вкладки коммитов в <a href="/symbolTrail/local-ui.html#символ">карточке символа</a> или поиска <a href="/symbolTrail/tools.html#find">find по SHA и задаче</a>. Для поиска коммитов конкретного автора используйте Git.</p><h2 id="подготовить-работу" tabindex="-1">Подготовить работу <a class="header-anchor" href="#подготовить-работу" aria-label="Permalink to &quot;Подготовить работу&quot;">​</a></h2><h3 id="написать-техническую-задачу" tabindex="-1">Написать техническую задачу <a class="header-anchor" href="#написать-техническую-задачу" aria-label="Permalink to &quot;Написать техническую задачу&quot;">​</a></h3><p>Опишите пожелание или найденную проблему как задачу: что нужно изменить и по каким критериям принять результат. Граф поможет найти реализацию, потребителей и соседние случаи.</p><div class="info custom-block"><p class="custom-block-title">Запрос агенту</p><p>Подготовь задачу на это изменение: опиши текущее и желаемое поведение, затронутые модули, ограничения, критерии приёмки и проверки. Неясные требования вынеси в вопросы.</p></div>',6)),s(o,{scenario:"task"}),l[7]||(l[7]=a('<div class="tip custom-block"><p class="custom-block-title">Результат</p><p>Техническая задача с учётом устройства проекта и проверяемыми условиями готовности.</p></div><p>Для контекста используйте <a href="/symbolTrail/tools.html#map">map</a>, <a href="/symbolTrail/tools.html#find">find</a> и <a href="/symbolTrail/tools.html#callers">callers</a>.</p><h3 id="написать-спецификацию" tabindex="-1">Написать спецификацию <a class="header-anchor" href="#написать-спецификацию" aria-label="Permalink to &quot;Написать спецификацию&quot;">​</a></h3><p>Опишите контракт изменения: входы, выходы, ошибки, совместимость и пограничные случаи. По текущему коду и его потребителям определите, как система работает сейчас.</p><div class="info custom-block"><p class="custom-block-title">Запрос агенту</p><p>Подготовь спецификацию изменения foo. Отдельно опиши текущее поведение, предлагаемый контракт, ошибки и совместимость. Подкрепи описание ссылками на код и отметь решения, которые ещё нужно согласовать.</p></div>',5)),s(o,{scenario:"spec"}),l[8]||(l[8]=a('<div class="tip custom-block"><p class="custom-block-title">Результат</p><p>Описание контракта и сценариев, по которым можно реализовать и проверить изменение.</p></div><p>Используйте <a href="/symbolTrail/tools.html#find">find</a>, <a href="/symbolTrail/tools.html#callees">callees</a> и <a href="/symbolTrail/tools.html#callers">callers</a> для поиска текущей реализации и её потребителей.</p><h3 id="работать-по-sdd-с-openspec" tabindex="-1">Работать по SDD с OpenSpec <a class="header-anchor" href="#работать-по-sdd-с-openspec" aria-label="Permalink to &quot;Работать по SDD с OpenSpec&quot;">​</a></h3><p>В комплекте SymbolTrail <code>openspec/config.yaml</code> выбирает схему <strong><code>graph-spec</code></strong> для <a href="https://github.com/Fission-AI/OpenSpec" target="_blank" rel="noreferrer">OpenSpec</a>: <code>proposal → impact → specs → design → tasks</code>. Агент описывает цель в <code>proposal</code> и собирает подтверждённые связи в <code>impact.md</code>. По ним он составляет спеку, затем дизайн и задачи с проверками.</p><div class="info custom-block"><p class="custom-block-title">Запрос агенту</p><p>Подготовь в OpenSpec изменение по схеме graph-spec: добавить в поиск фильтр по типу файла. Через MCP SymbolTrail исследуй реализацию и потребителей, зафиксируй факты в impact.md и обогати спеку требованиями совместимости. Подготовь задачи с проверками.</p></div>',5)),s(o,{scenario:"openspec"}),l[9]||(l[9]=a('<p><strong>Было:</strong> «Добавить фильтр по типу файла».</p><p><strong>Что выяснил агент (условный пример).</strong> <a href="/symbolTrail/tools.html#callers">callers</a> показал существующий вызов <code>foo(query)</code> из <code>b.ts</code>, а через <a href="/symbolTrail/tools.html#callees">callees</a> он получил сигнатуру <code>foo(query: string): Page</code> и исходящий вызов <code>bar(query)</code>. Проверив исходники, агент выявил условие совместимости: потребители без нового фильтра должны продолжить работать.</p><p><strong>Стало по шаблонам <code>graph-spec</code>:</strong></p><ul><li><strong><code>impact.md</code></strong>: точка <code>a.ts / foo</code> и строка потребителя <code>b.ts:12 · call · foo(query)</code>.</li><li><strong>Спека</strong>: <code>Signature: foo(query: string): Page</code>, <code>Return: Page</code>, <code>Keep: bar(query)</code>, <code>Outbound: bar</code> и <code>Anchor</code> объявления (<code>app</code>, <code>a.ts</code>, <code>foo</code>, строка 10). К требованию фильтра добавлен сценарий: «Когда фильтр не передан, тогда сохраняется прежнее поведение поиска».</li><li><strong><code>tasks.md</code></strong>: добавить необязательный фильтр и проверить прежний вызов <code>foo(query)</code>, фильтрацию и пагинацию через публичный вход.</li></ul><div class="tip custom-block"><p class="custom-block-title">Результат</p><p>Требование опирается на исследованный код. Найденный потребитель задаёт сценарий совместимости и проверку реализации.</p></div><h3 id="подобрать-и-написать-тесты" tabindex="-1">Подобрать и написать тесты <a class="header-anchor" href="#подобрать-и-написать-тесты" aria-label="Permalink to &quot;Подобрать и написать тесты&quot;">​</a></h3><p>Найдите существующие тестовые места и потребителей изменяемого кода. Затем выберите уровень проверки и случаи, которые нужно добавить.</p><div class="info custom-block"><p class="custom-block-title">Запрос агенту</p><p>Найди существующие тесты foo и предложи проверки для изменения. Добавь регрессионный случай через публичный вход и запусти подходящие тесты. Покажи результат запуска.</p></div>',8)),s(o,{scenario:"tests"}),l[10]||(l[10]=a('<div class="tip custom-block"><p class="custom-block-title">Результат</p><p>Набор проверок с обоснованием, новые тесты и результаты их запуска. Связь с тестовым файлом в индексе сама по себе не означает, что тест запущен или проходит.</p></div><p>Начните с <a href="/symbolTrail/tools.html#callers">callers</a>. Тестовые объявления также можно искать по имени через <a href="/symbolTrail/tools.html#find">find</a>.</p><h2 id="упростить-проект" tabindex="-1">Упростить проект <a class="header-anchor" href="#упростить-проект" aria-label="Permalink to &quot;Упростить проект&quot;">​</a></h2><h3 id="подготовить-рефакторинг-и-наити-повторное-использование" tabindex="-1">Подготовить рефакторинг и найти повторное использование <a class="header-anchor" href="#подготовить-рефакторинг-и-наити-повторное-использование" aria-label="Permalink to &quot;Подготовить рефакторинг и найти повторное использование&quot;">​</a></h3><p>Перед переносом кода или изменением API изучите зависимости и формы вызова. Найдите похожие реализации и проверьте, можно ли использовать существующее решение.</p><div class="info custom-block"><p class="custom-block-title">Запрос агенту</p><p>Подготовь план рефакторинга этой области. Найди похожую реализацию, проверь потребителей и предложи последовательность изменений с сохранением поведения и проверками после каждого шага.</p></div>',6)),s(o,{scenario:"refactor"}),l[11]||(l[11]=a('<div class="tip custom-block"><p class="custom-block-title">Результат</p><p>План изменений, список затрагиваемых мест и кандидаты на повторное использование.</p></div><p>Используйте <a href="/symbolTrail/tools.html#map">map</a>, <a href="/symbolTrail/tools.html#callers">callers</a> и поиск <a href="/symbolTrail/tools.html#find">find по фразе</a>. Для похожего по смыслу кода в UI нужны собранные <a href="/symbolTrail/indexing.html#векторы-для-поиска">векторы</a>.</p><h3 id="наити-неиспользуемыи-код" tabindex="-1">Найти неиспользуемый код <a class="header-anchor" href="#наити-неиспользуемыи-код" aria-label="Permalink to &quot;Найти неиспользуемый код&quot;">​</a></h3><p>Составьте список кандидатов, для которых индекс не нашёл входящих связей. Проверьте каждый случай перед удалением. Отдельно изучите публичные экспорты, регистрации и динамические обращения.</p><div class="info custom-block"><p class="custom-block-title">Запрос агенту</p><p>Найди кандидатов на удаление в этой области. Для каждого проверь входы, регистрации и публичное использование. Раздели подтверждённые случаи и места, где данных недостаточно.</p></div>',5)),s(o,{scenario:"dead"}),l[12]||(l[12]=a('<div class="tip custom-block"><p class="custom-block-title">Результат</p><p>Проверенный список кандидатов с обоснованием и планом проверок после удаления.</p></div><p>Начните с <a href="/symbolTrail/tools.html#dead">dead</a>, затем проверьте контекст через <a href="/symbolTrail/tools.html#callers">callers</a> и исходники.</p><h3 id="разобрать-зависимости-и-циклы" tabindex="-1">Разобрать зависимости и циклы <a class="header-anchor" href="#разобрать-зависимости-и-циклы" aria-label="Permalink to &quot;Разобрать зависимости и циклы&quot;">​</a></h3><p>Посмотрите, как связаны модули и репозитории. Найдите циклы импортов и места, где связи пересекают архитектурные границы.</p><div class="info custom-block"><p class="custom-block-title">Запрос агенту</p><p>Разбери зависимости этой области, найди циклы между файлами и репозиториями. Для каждого важного цикла покажи цепочку импортов и предложи варианты разделения ответственности.</p></div>',5)),s(o,{scenario:"cycles"}),l[13]||(l[13]=a('<div class="tip custom-block"><p class="custom-block-title">Результат</p><p>Обзор зависимостей, конкретные циклы и варианты изменения структуры. Цикл импорта требует изучения, но сам по себе не доказывает ошибку выполнения.</p></div><p>Используйте <a href="/symbolTrail/tools.html#map">map</a> и <a href="/symbolTrail/tools.html#cycles">cycles</a>.</p><h2 id="начать-работу" tabindex="-1">Начать работу <a class="header-anchor" href="#начать-работу" aria-label="Permalink to &quot;Начать работу&quot;">​</a></h2><p>Соберите индекс по <a href="/symbolTrail/getting-started.html">быстрому старту</a>, затем откройте <a href="/symbolTrail/local-ui.html">интерфейс</a> или <a href="/symbolTrail/mcp.html">подключите агента</a>. Точный формат запросов и доступные параметры приведены в <a href="/symbolTrail/tools.html">справочнике инструментов</a>.</p>',4))]))}});export{m as __pageData,n as default};
